SELECT p.subject_id, SUM(CASE WHEN e.charttime BETWEEN a.admittime AND a.admittime + INTERVAL '72 hours' THEN 1 ELSE 0 END) AS first_72h_glp1_injections, SUM(CASE WHEN e.charttime BETWEEN (a.dischtime - INTERVAL '72 hours') THEN 1 ELSE 0 END) AS final_72h_glp1_injections, (SUM(CASE WHEN e.charttime BETWEEN a.admittime AND a.admittime + INTERVAL '72 hours' THEN 1 ELSE 0 END) - SUM(CASE WHEN e.charttime BETWEEN (a.dischtime - INTERVAL '72 hours') THEN 1 ELSE 0 END)) AS absolute_change, (SUM(CASE WHEN e.charttime BETWEEN a.admittime AND a.admittime + INTERVAL '72 hours' THEN 1 ELSE 0 END)::FLOAT / NULLIF(SUM(CASE WHEN e.charttime BETWEEN (a.dischtime - INTERVAL '72 hours') THEN 1 ELSE 0 END), 0)) AS relative_change FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN emar e ON a.subject_id = e.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 55 AND a.admission_type = 'IM' AND (a.dischtime - a.admittime) > INTERVAL '72 hours' AND EXISTS (SELECT 1 FROM diagnoses_icd d WHERE d.subject_id = p.subject_id AND d.icd_code IN ('440.0', '440.1')) AND EXISTS (SELECT 1 FROM procedures_icd pr WHERE pr.subject_id = p.subject_id AND pr.icd_code IN ('440.0', '440.1')) GROUP BY p.subject_id;